import { test, expect } from "@playwright/test";

/**
 * Set List (Band tab): the 4-song set (opener/energy/ballad/finale) + a
 * gig-gated encore, each generated by the saved band. Runs against the live
 * server; the generation test drives a real /api/generate job.
 */

type Page = import("@playwright/test").Page;

async function tab(page: Page, name: RegExp) {
  const btn = page.locator("nav.tabbar").getByRole("button", { name });
  await expect(btn).toBeVisible();
  await expect(async () => {
    await btn.click();
    await expect(btn).toHaveClass(/on/, { timeout: 1500 });
  }).toPass({ timeout: 15000 });
}

function seedBand(page: Page, gigs: number) {
  return page.addInitScript((g) => {
    localStorage.setItem("aimusic.band", JSON.stringify({
      name: "The Testers", fans: g * 100, money: 0, gigs: g,
      role: "setlist",
      members: [
        { id: "m1", name: "Ava", part: "Vocals", genre: "rock_anthem_full", body: "girl" },
        { id: "m2", name: "Bo", part: "Guitar", genre: "rock_anthem_full", body: "boy" },
        { id: "m3", name: "Cy", part: "Bass", genre: "funk_full_song", body: "boy" },
        { id: "m4", name: "Di", part: "Drums", genre: "rock_anthem_full", body: "girl" },
      ],
    }));
  }, gigs);
}

async function openSetlist(page: Page) {
  await tab(page, /Band/);
  await page.locator(".role-picker").getByRole("button", { name: /Set List/ }).click();
}

test("the 4 set slots render and the encore is locked early", async ({ page }) => {
  await seedBand(page, 0);
  await page.goto("/app/");
  await openSetlist(page);

  for (const slot of ["opener", "energy", "ballad", "finale"]) {
    await expect(page.getByTestId(`slot-${slot}`)).toBeVisible();
  }
  const encore = page.getByTestId("slot-encore");
  await expect(encore).toHaveClass(/locked/);
  await expect(encore).toContainText(/Unlocks at 10 gigs/);
  await page.screenshot({ path: "test-screenshots/setlist.png", fullPage: true });
});

test("the encore unlocks once enough gigs are played", async ({ page }) => {
  await seedBand(page, 12);
  await page.goto("/app/");
  await openSetlist(page);

  const encore = page.getByTestId("slot-encore");
  await expect(encore).not.toHaveClass(/locked/);
  await expect(page.getByTestId("gen-encore")).toBeVisible();
});

test("generating the opener fills the slot with a band song", async ({ page }) => {
  test.setTimeout(90_000);   // a real generation job
  await seedBand(page, 0);
  await page.goto("/app/");
  await openSetlist(page);

  await page.getByTestId("gen-opener").click();
  // The slot fills with the saved block name once the job completes.
  await expect(page.getByTestId("slot-opener").getByTestId("slot-song"))
    .toContainText(/Testers — Opener/, { timeout: 80_000 });
  await expect(page.getByTestId("setlist-msg")).toContainText(/ready/);
});
